  "settings": {
    "index.mode": "time_series",
    "index.routing_path": "key"
  },
  "mappings": {
    "properties": {
      "key": {
        "type": "keyword",
        "time_series_dimension": true
      },
      "val": {
        "type": "double"
      }
    }
  }
}
```
